entries[430584] = { ["name"] = "Saat der Flamme", ["text"] = "Unbegrenzte Reichweite\nSofort\nSaaten der Flamme, die nicht von einem Spielercharakter zerquetscht werden, sind nach 5 Sek. ein ' Flammender Baum '.\n\nWenn ein Spielercharakter auf eine ' Saat der Flamme ' tritt, wird diese zerstört. Der Spielercharakter erleidet dabei 108785 Feuerschaden und wird 10 Sek. lang mit ' Keimende Aura ' belegt." }
