entries[430607] = { ["name"] = "Boshaftes Fläschchen der klassischen Geister", ["text"] = "Wirken in 2 sek. 2\nReagenzien:\nBoshaftes Fläschchen der Ehre , Orbinid (6)\nVerkäufer:\nHotharn\nZone:\nDornogal\nKosten:\n7500\n\nBenutzen: Trinkt dies, um Eure Manaregeneration um 8% zu erhöhen, wenn Ihr 5 Sek. lang keinen hilfreichen Zauber gewirkt habt, der Mana kostet.\n\nErhaltene Ehre ist um 15% erhöht.\n\nHält 1 Stunde lang und über den Tod hinaus an. Die Benutzung eines identischen Fläschchens verlängert die Dauer um 1 Stunde\n71" }
entries[430608] = { ["name"] = "Boshaftes Fläschchen der Ehre", ["text"] = "Wirken in 2 sek. 2\nReagenzien:\nMykopracht (16), Segensblume (8), Goldbesetzte Phiole (2)\nVerkäufer:\nHotharn\nZone:\nDornogal\nKosten:\n7500\n\nBenutzen: Trinkt dies, um Eure erhaltene Ehre um 15% zu erhöhen. Kann in allen gewerteten und ungewerteten PvP-Umgebungen eingesetzt werden.\n\nHält 1 Stunde lang und über den Tod hinaus an. Die Benutzung eines identischen Fläschchens verlängert die Dauer um 1 Stunde\n71" }
