entries[430611] = { ["name"] = "Boshaftes Fläschchen der Abrisskugel", ["text"] = "Wirken in 2 sek. 2\nReagenzien:\nBoshaftes Fläschchen der Ehre , Arathors Speer (6)\nVerkäufer:\nHotharn\nZone:\nDornogal\nKosten:\n7500\n\nBenutzen: Todesstöße von Spielercharakteren erhöhen 20 Sek. lang Euren verursachten Schaden um 8% und Euren erlittenen Schaden um 4%. Bis zu 5-mal stapelbar. Wenn Ihr getötet werdet, während dieser Effekt aktiv ist, erhält Euer Angreifer einen Teil dieser Macht.\n\nErhaltene Ehre ist um 15% erhöht.\n\nHält 1 Stunde lang und über den Tod hinaus an. Die Benutzung eines identischen Fläschchens verlängert die Dauer um 1 Stunde\n71" }
