entries[431038] = { ["name"] = "Frostfeuermeisterschaft", ["text"] = "Eure schädlichen Feuerzauber erzeugen 1 Stapel 'Feuermeisterschaft' und Frostzauber erzeugen 1 Stapel 'Frostmeisterschaft'.\n\n'Feuermeisterschaft' erhöht 14 Sek. lang Euer Tempo um 2% und 'Frostmeisterschaft' Eure Meisterschaft um 2%, jeweils bis zu 6-mal stapelbar.\n\nWenn Stapel hinzukommen, wird die Dauer nicht zurückgesetzt." }
entries[431039] = { ["name"] = "Frostmeisterschaft", ["text"] = "Sofort\nEure schädlichen Feuerzauber erzeugen 1 Stapel 'Feuermeisterschaft' und Frostzauber erzeugen 1 Stapel 'Frostmeisterschaft'.\n\n'Feuermeisterschaft' erhöht 14 Sek. lang Euer Tempo um 2% und 'Frostmeisterschaft' Eure Meisterschaft um 2%, jeweils bis zu 6-mal stapelbar.\n\nWenn Stapel hinzukommen, wird die Dauer nicht zurückgesetzt." }
entries[431040] = { ["name"] = "Feuermeisterschaft", ["text"] = "Sofort\nEure schädlichen Feuerzauber erzeugen 1 Stapel 'Feuermeisterschaft' und Frostzauber erzeugen 1 Stapel 'Frostmeisterschaft'.\n\n'Feuermeisterschaft' erhöht 14 Sek. lang Euer Tempo um 2% und 'Frostmeisterschaft' Eure Meisterschaft um 2%, jeweils bis zu 6-mal stapelbar.\n\nWenn Stapel hinzukommen, wird die Dauer nicht zurückgesetzt." }
