entries[431044] = { ["name"] = "Frostfeuerblitz", ["text"] = "2% von Grundmana 40 Meter Reichweite\nWirken in 2 sek.\nSchleudert einen Frostfeuerblitz auf den Gegner, der (126.5% der Zaubermacht) Frostfeuerschaden verursacht, die Bewegungsgeschwindigkeit um 50 % verringert und im Verlauf von 8 Sek. (46% der Zaubermacht) zusätzlichen Frostfeuerschaden verursacht.\n\n'Frostfeuerblitz' erzeugt Stapel von 'Feuermeisterschaft' und 'Frostmeisterschaft'." }
