entries[431442] = { ["name"] = "Chronoflamme", ["text"] = "Bewahrung\n'Lebendige Flamme' wird mit Bronzemagie verstärkt und wiederholt 15% des Schadens oder der Heilung, die Ihr in den letzten 5 Sek. dem Ziel zugefügt bzw. die Ihr beim Ziel hervorgerufen habt, in arkaner Form, bis zu [(Zaubermacht * 2.5) * (1 + Vielseitigkeit)].\n\nVerheerung, Verstärkung\n'Lebendige Flamme' wird mit Bronzemagie verstärkt und wiederholt 25% des Schadens oder der Heilung, die Ihr in den letzten 5 Sek. dem Ziel zugefügt bzw. die Ihr beim Ziel hervorgerufen habt, in arkaner Form, bis zu [(Zaubermacht * 2.5) * (1 + Vielseitigkeit)]." }
entries[431443] = { ["name"] = "Chronoflammen", ["text"] = "12% von Grundmana 25 Meter Reichweite\nWirken in 2 sek.\nVerheerung, Verstärkung\nWirbelt 'Chronoflammen' auf Euer Ziel. Fügt einem Gegner (232.001% der Zaubermacht) Feuerschaden zu oder heilt einen Verbündeten um (466% der Zaubermacht) Gesundheit.\n\nBronzemagie wiederholt 25% des Schadens oder der Heilung, die Ihr in den letzten 5 Sek. dem Ziel zugefügt bzw. die Ihr beim Ziel hervorgerufen habt, in arkaner Form, bis zu [(Zaubermacht * 2.5) * (1 + Vielseitigkeit)].\n\nBewahrung\nWirbelt 'Chronoflammen' auf Euer Ziel. Heilt einen Verbündeten um (466% der Zaubermacht) Gesundheit oder fügt einem Gegner (232.001% der Zaubermacht) Feuerschaden zu.\n\nBronzemagie wiederholt 15% des Schadens oder der Heilung, die Ihr in den letzten 5 Sek. dem Ziel zugefügt bzw. die Ihr beim Ziel hervorgerufen habt, in arkaner Form, bis zu [(Zaubermacht * 2.5) * (1 + Vielseitigkeit)]." }
entries[431444] = { ["name"] = "Schockierend aufgedeckt", ["text"] = "Unbegrenzte Reichweite\nSofort\nErhöht die Verstohlenheitsaufdeckung. Alle 1 Sek. versucht das Licht, einen innerhalb von 20 Metern verborgenen Gegner anzugreifen.\n\nHält (ja nach Herstellungsqualität) 15 bis 25 Sek. lang an." }
