entries[431460] = { ["name"] = "Morgenlicht", ["text"] = "Nachdem Ihr [ Heilig : 'Heiliges Prisma' oder 'Barriere des Glaubens' ] [ Vergeltung : 'Aschewelle' ] einsetzt, wirkt Eure nächste Fähigkeit, die Heilige Kraft verbraucht, garantiert 1 Instanzen von 'Morgenlicht'.\n(2s Abklingzeit)" }
entries[431462] = { ["name"] = "Wille der Morgendämmerung", ["text"] = "Sofort\nBewegungsgeschwindigkeit um 5% erhöht, während Ihr mehr als 80% Gesundheit habt.\n\nWenn Eure Gesundheit unter 35% fällt, wird Eure Bewegungsgeschwindigkeit 5 Sek. lang um 40% erhöht. Kann nicht mehr als einmal alle 1 Min. auftreten." }
