entries[431491] = { ["name"] = "Besudeltes Schlitzen", ["text"] = "40 Meter Reichweite\nWirken in 2 sek.\nBringt dem Ziel eine blutende Wunde bei und fügt ihm 7273348 körperlichen Schaden zu. Die Blutung verursacht 8 Sek. lang alle 0.5 Sek. 484890 körperlichen Schaden. Dieser Effekt ist stapelbar." }
