entries[431562] = { ["name"] = "Errettung des Lichts", ["text"] = "Sofort\nWenn Ihr einen Himmelshammer herabruft, erhaltet Ihr einen Stapel von 'Errettung des Lichts'.\n\nWährend [ Schutz : 'Auge von Tyr' /\n\nVergeltung\n'Aschewelle' ] und 'Hammer des Lichts' nicht verfügbar sind, verbraucht Ihr 60 Stapel von 'Errettung des Lichts', um 'Hammer des Lichts' kostenlos ein zusätzliches Mal einsetzen zu können." }
