entries[431570] = { ["name"] = "Stampfen", ["text"] = "Sofort\nFeuert einen Schuss ab, der den Gegner zerfetzt und ihm im Verlauf von 8 Sek. 4 Blutungsschaden zufügt.\n\nVersetzt Euren Begleiter in eine Raserei, die sein Angriffstempo 8 Sek. lang um 30% erhöht. Bis zu 3-mal stapelbar.\n\nErzeugt im Verlauf von 8 Sek. (7 * 8 / 2) Fokus." }
